/**
 * Operation Control Registry — the single source of truth for security
 * metadata on every API operation.
 *
 * Every route in backend/src/routes/ and backend/src/credit/routes/ MUST have
 * a corresponding entry here. The coverage test (operation-control.coverage.test.ts)
 * will fail the build if any operation is missing or duplicate.
 *
 * Batch 1 (P01): Critical user, file, notification, PDF, export endpoints.
 * Batch 2 (P02 T9): Request domain endpoints — secured with authorizeResource.
 *
 * @see backend/src/security/operation-control.types.ts
 */

